import { getRedisClient } from './redis';
import { RateLimitRule, getEndpointConfig, getWhitelistedIPs } from './rate-limit-config';

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  resetAt: number;        // Unix timestamp when the window resets
  retryAfter?: number;    // Seconds until the request can be retried
  limit: number;
  current: number;
}

export interface RateLimitInfo {
  identifier: string;     // User ID or IP
  identifierType: 'user' | 'ip';
  path: string;
  method: string;
  timestamp: number;
  allowed: boolean;
}

const RATE_LIMIT_PREFIX = 'ratelimit:';
const VIOLATION_PREFIX = 'ratelimit:violation:';
const STATS_PREFIX = 'ratelimit:stats:';

/**
 * Sliding Window Rate Limiter using Redis sorted sets
 * 
 * Algorithm:
 * 1. Store each request as a member in a sorted set with score = timestamp
 * 2. Remove all members older than the window
 * 3. Count remaining members
 * 4. If count < limit, add new request and allow
 * 5. Otherwise, deny the request
 */
export async function checkRateLimit(
  identifier: string,
  path: string,
  isAuthenticated: boolean
): Promise<RateLimitResult> {
  const redis = await getRedisClient();
  const config = getEndpointConfig(path);
  const rule = isAuthenticated ? config.authenticated : config.anonymous;
  
  const now = Date.now();
  const windowStart = now - rule.windowMs;
  const key = `${RATE_LIMIT_PREFIX}${identifier}:${path}`;
  
  // Use Redis transaction for atomicity
  const multi = redis.multi();
  
  // Remove expired entries (older than window start)
  multi.zRemRangeByScore(key, 0, windowStart);
  
  // Count current requests in window
  multi.zCard(key);
  
  // Execute transaction
  const results = await multi.exec();
  const currentCount = results[1] as number;
  
  if (currentCount < rule.maxRequests) {
    // Add this request
    await redis.zAdd(key, { score: now, value: `${now}:${Math.random()}` });
    // Set expiry on the key (window duration + buffer)
    await redis.expire(key, Math.ceil(rule.windowMs / 1000) + 60);
    
    // Track stats
    await trackRequestStats(identifier, path, true);
    
    return {
      allowed: true,
      remaining: rule.maxRequests - currentCount - 1,
      resetAt: now + rule.windowMs,
      limit: rule.maxRequests,
      current: currentCount + 1,
    };
  }
  
  // Rate limit exceeded
  // Find the oldest request in the window to calculate retry-after
  const oldestRequests = await redis.zRange(key, 0, 0);
  let retryAfter = Math.ceil(rule.windowMs / 1000);
  
  if (oldestRequests.length > 0) {
    const oldestTimestamp = parseInt(oldestRequests[0].split(':')[0]);
    retryAfter = Math.ceil((oldestTimestamp + rule.windowMs - now) / 1000);
  }
  
  // Track violation
  await trackViolation(identifier, path);
  await trackRequestStats(identifier, path, false);
  
  return {
    allowed: false,
    remaining: 0,
    resetAt: now + retryAfter * 1000,
    retryAfter: Math.max(1, retryAfter),
    limit: rule.maxRequests,
    current: currentCount,
  };
}

/**
 * Check if an IP is whitelisted
 */
export function isWhitelisted(ip: string): boolean {
  const whitelist = getWhitelistedIPs();
  return whitelist.includes(ip);
}

/**
 * Track rate limit violations for monitoring
 */
async function trackViolation(identifier: string, path: string): Promise<void> {
  const redis = await getRedisClient();
  const now = Date.now();
  const hourKey = `${VIOLATION_PREFIX}${Math.floor(now / 3600000)}`;
  
  // Store violation info
  await redis.hIncrBy(hourKey, identifier, 1);
  await redis.expire(hourKey, 86400 * 7); // Keep for 7 days
  
  // Log to console
  console.warn(`[RateLimit] Violation: identifier=${identifier}, path=${path}, timestamp=${new Date(now).toISOString()}`);
}

/**
 * Track request statistics
 */
async function trackRequestStats(identifier: string, path: string, allowed: boolean): Promise<void> {
  const redis = await getRedisClient();
  const now = Date.now();
  const hourKey = `${STATS_PREFIX}hour:${Math.floor(now / 3600000)}`;
  const dayKey = `${STATS_PREFIX}day:${Math.floor(now / 86400000)}`;
  
  // Increment request counts
  const multi = redis.multi();
  multi.hIncrBy(hourKey, `${identifier}:total`, 1);
  multi.hIncrBy(hourKey, `${identifier}:${allowed ? 'allowed' : 'blocked'}`, 1);
  multi.hIncrBy(dayKey, `${identifier}:total`, 1);
  multi.hIncrBy(dayKey, `${identifier}:${allowed ? 'allowed' : 'blocked'}`, 1);
  multi.expire(hourKey, 86400 * 2);  // Keep hourly stats for 2 days
  multi.expire(dayKey, 86400 * 30);  // Keep daily stats for 30 days
  
  await multi.exec();
}

/**
 * Get top requesters for dashboard
 */
export async function getTopRequesters(limit: number = 20): Promise<Array<{
  identifier: string;
  total: number;
  blocked: number;
  allowed: number;
}>> {
  const redis = await getRedisClient();
  const now = Date.now();
  const hourKey = `${STATS_PREFIX}hour:${Math.floor(now / 3600000)}`;
  
  const stats = await redis.hGetAll(hourKey);
  const aggregated: Record<string, { total: number; blocked: number; allowed: number }> = {};
  
  for (const [key, value] of Object.entries(stats)) {
    const [identifier, type] = key.split(':');
    if (!aggregated[identifier]) {
      aggregated[identifier] = { total: 0, blocked: 0, allowed: 0 };
    }
    if (type === 'total') {
      aggregated[identifier].total = parseInt(value);
    } else if (type === 'blocked') {
      aggregated[identifier].blocked = parseInt(value);
    } else if (type === 'allowed') {
      aggregated[identifier].allowed = parseInt(value);
    }
  }
  
  return Object.entries(aggregated)
    .map(([identifier, data]) => ({ identifier, ...data }))
    .sort((a, b) => b.total - a.total)
    .slice(0, limit);
}

/**
 * Get violation patterns
 */
export async function getViolationPatterns(hours: number = 24): Promise<Array<{
  identifier: string;
  violations: number;
  hourlyBreakdown: Array<{ hour: number; count: number }>;
}>> {
  const redis = await getRedisClient();
  const now = Date.now();
  const patterns: Record<string, { violations: number; hourly: Record<number, number> }> = {};
  
  for (let i = 0; i < hours; i++) {
    const hourKey = `${VIOLATION_PREFIX}${Math.floor((now - i * 3600000) / 3600000)}`;
    const violations = await redis.hGetAll(hourKey);
    
    for (const [identifier, count] of Object.entries(violations)) {
      if (!patterns[identifier]) {
        patterns[identifier] = { violations: 0, hourly: {} };
      }
      const hourNum = (24 - i) % 24;
      patterns[identifier].violations += parseInt(count);
      patterns[identifier].hourly[hourNum] = parseInt(count);
    }
  }
  
  return Object.entries(patterns)
    .map(([identifier, data]) => ({
      identifier,
      violations: data.violations,
      hourlyBreakdown: Object.entries(data.hourly)
        .map(([hour, count]) => ({ hour: parseInt(hour), count }))
        .sort((a, b) => a.hour - b.hour),
    }))
    .sort((a, b) => b.violations - a.violations);
}

/**
 * Get overall stats
 */
export async function getOverallStats(): Promise<{
  totalRequests: number;
  blockedRequests: number;
  uniqueIdentifiers: number;
  topEndpoints: Array<{ endpoint: string; count: number }>;
}> {
  const redis = await getRedisClient();
  const now = Date.now();
  const hourKey = `${STATS_PREFIX}hour:${Math.floor(now / 3600000)}`;
  
  const stats = await redis.hGetAll(hourKey);
  let totalRequests = 0;
  let blockedRequests = 0;
  const identifiers = new Set<string>();
  
  for (const [key, value] of Object.entries(stats)) {
    const [identifier, type] = key.split(':');
    identifiers.add(identifier);
    if (type === 'total') {
      totalRequests += parseInt(value);
    } else if (type === 'blocked') {
      blockedRequests += parseInt(value);
    }
  }
  
  return {
    totalRequests,
    blockedRequests,
    uniqueIdentifiers: identifiers.size,
    topEndpoints: [], // Would need additional tracking for endpoints
  };
}
